  {
    "text": "The study involved 78 Spanish-speaking, right-handed adults aged 50–65 years with a family history of Alzheimer's disease.",
    "topic": "Study participants"
  },
  {
    "text": "Baseline executive functioning was examined to predict initial performance and learning trajectories across two adaptive executive training tasks: task switching and n-back.",
    "topic": "Predictive factors"
  },
  {
    "text": "Neuropsychological assessments were conducted before and after the adaptive executive training intervention.",
    "topic": "Assessment timing"
  },
  {
    "text": "The research aimed to determine if learning trajectories during the training tasks are associated with post-intervention cognitive outcomes.",
    "topic": "Outcome association"
  },
  {
    "text": "The participants were middle-aged adults at increased risk for Alzheimer's disease due to a family history of the condition.",
    "topic": "Risk profile"
  }
]
